rules:
  - id: init-variables-with-default-value
    message: >-
      Uninitialized variables are assigned with the types default value.
      Explicitly initializing a variable with its default value costs unnecessary gas.
    metadata:
      references:
        - https://github.com/byterocket/c4-common-issues/blob/main/0-Gas-Optimizations.md/#g001---dont-initialize-variables-with-default-value
      category: performance
      technology:
        - solidity
    patterns:
      - pattern-either:
          - pattern: $TYPE $VAR = 0;
          - pattern: $TYPE $VAR = false;
          - pattern: $TYPE $VAR = "";
          - pattern: $TYPE $VAR = '';
      - pattern-not: $TYPE constant $VAR = ...;
      - pattern-not-inside: |
          contract $C {
            ...
            $TYPE immutable $VAR = ...;
            ...
          }
      - pattern-not-inside: |
          function $F(...) {
            ...
          }
    languages:
      - solidity
    severity: INFO

rules:
  - id: state-variable-read-in-a-loop
    message: Replace state variable reads and writes within loops with local variable reads and writes.
    metadata:
      category: performance
      technology:
        - solidity
      references:
        - https://github.com/devanshbatham/Solidity-Gas-Optimization-Tips#10--replace-state-variable-reads-and-writes-within-loops-with-local-variable-reads-and-writes
    patterns:
      - pattern-either:
          - pattern-inside: |
              contract $C {
                ...
                $TYPE $X = ... ;
                ...
              }
          - pattern-inside: |
              contract $C {
                ...
                $TYPE $X;
                ...
              }
      - pattern-not-inside: |
            contract $C {
                ...
                $TYPE immutable $X;
                ...
            }
      - pattern-not-inside: |
            contract $C {
                ...
                $TYPE immutable $X = ...;
                ...
            }
      - pattern-not-inside: |
            contract $C {
                ...
                $TYPE constant $X = ...;
                ...
            }
      - pattern: $X
      - pattern-either:
        - pattern-inside: |
            for (...) {
              ...
            }
        - pattern-inside: |
            while (...) {
              ...
            }
    languages:
      - solidity
    severity: INFO

rules:
  - id: accessible-selfdestruct
    severity: ERROR
    languages:
      - solidity
    message: Contract can be destructed by anyone in $FUNC
    metadata:
      category: security
      technology:
        - solidity
      cwe: "CWE-284: Improper Access Control"
