              ...
              require(<... msg.sender ...>, ...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              assert(<... msg.sender ...>, ...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              require(<... _msgSender ...>, ...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              assert(<... _msgSender ...>, ...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              if (<... msg.sender ...>) {
                ...
              }
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              if (<... _msgSender ...>) {
                ...
              }
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              onlyOwner(...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              requireOwner(...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              _requireOwnership(...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              $C._enforceIsContractOwner(...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              $C._enforceOwner(...);
              ...
            }
        - pattern-not: |
            function $FUNC(...) {
              ...
              $C.enforceIsContractOwner(...);
              ...
            }
    pattern-sinks:
      - pattern-either:
        - pattern: selfdestruct(...);
        - pattern: suicide(...);

